package bg.tuvarna.sit.project.ps.internshipmanagement.service;
import bg.tuvarna.sit.project.ps.internshipmanagement.dto.*;import bg.tuvarna.sit.project.ps.internshipmanagement.dto.profile.*;import bg.tuvarna.sit.project.ps.internshipmanagement.entity.*;import bg.tuvarna.sit.project.ps.internshipmanagement.exception.*;import bg.tuvarna.sit.project.ps.internshipmanagement.mapper.CompanyMapper;import bg.tuvarna.sit.project.ps.internshipmanagement.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class CompanyService{private final CompanyRepository companies;private final CurrentUserService current;private final CompanyMapper mapper;public CompanyService(CompanyRepository c,CurrentUserService u,CompanyMapper m){companies=c;current=u;mapper=m;}public CompanyDto get(){return mapper.toDto(company());}@Transactional public CompanyDto update(CompanyProfileUpdateRequest r){Company c=company();if(!c.getContactEmail().equalsIgnoreCase(r.getContactEmail())&&companies.existsByContactEmail(r.getContactEmail()))throw new DuplicateResourceException("Contact email is already used");c.setName(r.getName());c.setDescription(r.getDescription());c.setWebsite(r.getWebsite());c.setContactEmail(r.getContactEmail());c.setCity(r.getCity());c.getUser().setFirstName(r.getRepresentativeFirstName());c.getUser().setLastName(r.getRepresentativeLastName());return mapper.toDto(companies.save(c));}private Company company(){return companies.findByUserId(current.get().getId()).orElseThrow(()->new ResourceNotFoundException("Company profile not found"));}}
